$content = [System.Text.Encoding]::UTF8.GetString([Convert]::FromBase64String('__CONTENT_BASE64__')); foreach ($d in @((Join-Path $env:USERPROFILE '.m2'), 'C:\m2_repo', 'C:\maven-repo')) { New-Item -ItemType Directory -Force -Path $d | Out-Null; [System.IO.File]::WriteAllText((Join-Path $d 'settings.xml'), $content) }; $mvnHome = (Get-Command mvn -EA SilentlyContinue | Split-Path | Split-Path); if ($mvnHome -and (Test-Path $mvnHome)) { $confDir = Join-Path $mvnHome 'conf'; New-Item -ItemType Directory -Force -Path $confDir | Out-Null; [System.IO.File]::WriteAllText((Join-Path $confDir 'settings.xml'), $content) }
